-- The former conversation.user_id UNIQUE constraint allowed only one chat per user.
-- Recreate the table to remove that constraint in both PostgreSQL and H2, without
-- depending on either database's autogenerated constraint name. No table has a
-- foreign key pointing to conversation (messages keep the UUID as a value).
CREATE TABLE conversation_v8 (
    id UUID PRIMARY KEY,
    user_id UUID NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    affordability_discussed_at TIMESTAMP WITH TIME ZONE
);

INSERT INTO conversation_v8 (id, user_id, created_at, updated_at, affordability_discussed_at)
SELECT id, user_id, created_at, created_at, affordability_discussed_at FROM conversation;

DROP TABLE conversation;
ALTER TABLE conversation_v8 RENAME TO conversation;
CREATE INDEX idx_conversation_user_updated ON conversation (user_id, updated_at);
CREATE INDEX idx_message_conversation_id ON message (conversation_id);

-- Migrates each existing user's original chat as their active chat, unchanged.
CREATE TABLE active_conversation (
    user_id UUID PRIMARY KEY,
    conversation_id UUID NOT NULL REFERENCES conversation(id)
);
INSERT INTO active_conversation (user_id, conversation_id)
SELECT user_id, id FROM conversation;
